using sv_c054ae54a0df43c09009858296172c61.Models;

namespace sv_c054ae54a0df43c09009858296172c61.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

using sv_c054ae54a0df43c09009858296172c61.Models;

namespace sv_c054ae54a0df43c09009858296172c61.Services;

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> CuisineRecipes = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic Neapolitan pizza with tomato, mozzarella, and basil.", 30),
            new(2, "Spaghetti Carbonara", "Creamy pasta with eggs, pecorino, guanciale, and black pepper.", 25),
            new(3, "Risotto alla Milanese", "Saffron-infused Arborio rice cooked slowly in broth.", 45),
        },
        [2] = new List<Recipe>
        {
            new(4, "Kung Pao Chicken", "Spicy stir-fried chicken with peanuts, vegetables, and chili peppers.", 35),
            new(5, "Mapo Tofu", "Silken tofu in a fiery sauce of doubanjiang, ground pork, and Sichuan peppercorns.", 20),
            new(6, "Xiaolongbao", "Steamed soup dumplings filled with pork and a rich broth.", 60),
        },
        [3] = new List<Recipe>
        {
            new(7, "Tacos al Pastor", "Marinated pork tacos with pineapple, onion, and cilantro.", 40),
            new(8, "Chicken Enchiladas", "Corn tortillas rolled around chicken and covered in chili sauce and cheese.", 50),
            new(9, "Guacamole", "Fresh avocado dip with lime, cilantro, onion, and jalapeño.", 10),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (CuisineRecipes.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_c054ae54a0df43c09009858296172c61.Models
@using sv_c054ae54a0df43c09009858296172c61.Services
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (errorMessage is not null)
{
    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
        <span>@errorMessage</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (recipes is null && errorMessage is null)
{
    <p><em>Loading recipes…</em></p>
}
else if (recipes is not null)
{
    @if (isRefreshing)
    {
        <div class="text-muted mb-2"><small>Refreshing…</small></div>
    }

    <div class="mb-3">
        <label class="form-label me-2">Sort:</label>
        <a href="@GetSortUrl("newest")" class="btn btn-sm @(CurrentSort == "newest" ? "btn-primary" : "btn-outline-primary") me-1">Newest</a>
        <a href="@GetSortUrl("popular")" class="btn btn-sm @(CurrentSort == "popular" ? "btn-primary" : "btn-outline-primary")">Popular</a>
    </div>

    @{ var sorted = GetSortedRecipes(); }
    @if (sorted.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in sorted)
            {
                <div class="col-md-4 mb-3">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">@recipe.Description</p>
                            <span class="badge bg-secondary">@recipe.PrepTimeMinutes min</span>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? recipes;
    private string? errorMessage;
    private bool isRefreshing;
    private int loadedCuisineId;

    private CancellationTokenSource? loadCts;
    private readonly CancellationTokenSource disposeCts = new();

    private string CurrentSort => string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
        ? "popular"
        : "newest";

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == loadedCuisineId && recipes is not null)
        {
            // Only the sort parameter changed — no reload needed.
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        if (loadCts is not null)
        {
            await loadCts.CancelAsync();
            loadCts.Dispose();
        }

        loadCts = CancellationTokenSource.CreateLinkedTokenSource(disposeCts.Token);

        var cuisineId = CuisineId;
        isRefreshing = recipes is not null;
        errorMessage = null;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(cuisineId, loadCts.Token);

            recipes = result;
            loadedCuisineId = cuisineId;
            errorMessage = null;
        }
        catch (OperationCanceledException) when (disposeCts.IsCancellationRequested)
        {
            // Component is being disposed — do nothing.
        }
        catch (OperationCanceledException)
        {
            // A newer load superseded this one — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (recipes is null) return new();

        return CurrentSort == "popular"
            ? recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : recipes.OrderByDescending(r => r.Id).ToList();
    }

    private string GetSortUrl(string sort)
    {
        return Navigation.GetUriWithQueryParameter("sort", sort);
    }

    public void Dispose()
    {
        disposeCts.Cancel();
        disposeCts.Dispose();
        loadCts?.Cancel();
        loadCts?.Dispose();
    }
}

