+            // Component is being disposed — do nothing.
+        }
+        catch (OperationCanceledException)
+        {
+            // A newer load superseded this one — do nothing.
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
+            errorMessage = "The request timed out. Please try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
+            errorMessage = "Something went wrong while loading recipes. Please try again.";
+        }
+        finally
+        {
+            isRefreshing = false;
+        }
+    }
+
+    private async Task RetryAsync()
+    {
+        await LoadRecipesAsync();
+    }
+
+    private List<Recipe> GetSortedRecipes()
+    {
+        if (recipes is null) return new();
+
+        return CurrentSort == "popular"
+            ? recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
+            : recipes.OrderByDescending(r => r.Id).ToList();
+    }
+
+    private string GetSortUrl(string sort)
+    {
+        return Navigation.GetUriWithQueryParameter("sort", sort);
+    }
+
+    public void Dispose()
+    {
+        disposeCts.Cancel();
+        disposeCts.Dispose();
+        loadCts?.Cancel();
+        loadCts?.Dispose();
+    }
+}
